<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('activity.view');$pdo=staff_db();$rows=$pdo->query("SELECT l.*,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) staff_name FROM activity_logs l LEFT JOIN staff s ON s.id=l.staff_id ORDER BY l.created_at DESC LIMIT 250")->fetchAll();$pageTitle='Activity Logs';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Audit</p><h1>Activity logs</h1></div></div><section class="staff-panel table-panel"><table><thead><tr><th>Time</th><th>Staff</th><th>Action</th><th>Entity</th><th>Description</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h(date('j M Y, g:i A',strtotime($r['created_at']))) ?></td><td><?= h(trim($r['staff_name'])?:'System') ?></td><td><code><?= h($r['action']) ?></code></td><td><?= h(($r['entity_type']?:'—').($r['entity_id']?' #'.$r['entity_id']:'')) ?></td><td><?= h($r['description']?:'—') ?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
